from pathlib import Path
import sys
root = Path('compiler/test/Dialect/SSAVC4')
future = ['ssavc4.load_imm', 'ssavc4.element_number', 'ssavc4.alu.', 'ssavc4.make_flags', 'ssavc4.tmu.', 'ssavc4.vpm.', 'ssavc4.vdw.', 'ssavc4.dma.']
pure_marker = Path('compiler/include/vc4/Dialect/SSAVC4/IR/SSAVC4Ops.td')
type_marker = Path('compiler/include/vc4/Dialect/SSAVC4/IR/SSAVC4Types.td')
owners = {
  'ssavc4.load_imm': pure_marker,
  'ssavc4.element_number': pure_marker,
  'ssavc4.alu.': pure_marker,
  'ssavc4.make_flags': pure_marker,
  'ssavc4.vdw.': Path('compiler/test/Dialect/SSAVC4/vdw-store-roundtrip.mlir'),
  'ssavc4.dma.': Path('compiler/test/Dialect/SSAVC4/dma-roundtrip.mlir'),
}
def owner_ready(token, line):
    if token == 'ssavc4.tmu.':
        if '!ssavc4.tmu.desc' in line:
            return type_marker.exists()
        return Path('compiler/test/Dialect/SSAVC4/tmu-direct-roundtrip.mlir').exists()
    if token == 'ssavc4.vpm.':
        if '!ssavc4.vpm.desc' in line:
            return type_marker.exists()
        return Path('compiler/test/Dialect/SSAVC4/vpm-shared-roundtrip.mlir').exists()
    marker = owners[token]
    return marker.exists()
bad = []
for path in sorted(root.glob('*.mlir')):
    text = path.read_text(encoding='utf-8', errors='replace')
    for lineno, line in enumerate(text.splitlines(), 1):
        for token in future:
            if token in line and not owner_ready(token, line):
                bad.append(f'{path}:{lineno}: {token}')
if bad:
    print('future SSAVC4 tests are active before their owning slice products exist:')
    print('\n'.join(bad[:100]))
    sys.exit(1)
print('ssavc4 scaffold active-test hygiene ok')

